import { Controller, Get, Post, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const REPORT_TYPES = [
  'WITHHOLDING_STATUS',
  'TUITION_REPAYMENT',
  'LOCAL_INCOME_TAX',
  'RESIDENT_TAX_EMPLOYER',
  'PAYMENT_STATEMENT',
  'SUBMISSION_SUMMARY',
];
const STATUSES = ['미확정', '확정'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 가정: 귀속연월·지급연월은 YYYYMM 형식
const MONTH_PATTERN = /^[0-9]{6}$/;
// 가정: 전자신고 파일은 확정된 신고 자료를 텍스트 파일로 내려준다
const E_FILING_CONTENT_TYPE = 'text/plain; charset=utf-8';

@Controller('api/v1')
export class FnSfr02301Controller {
  @Post('/withholding-reports')
  @HttpCode(200)
  async createWithholdingReport(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const paydayId = Number(data['paydayId']);
    const attributionMonth = data['attributionMonth'];
    const paymentMonth = data['paymentMonth'];
    const reportDivision = data['reportDivision'];
    const reportType = data['reportType'];
    const reportData = data['reportData'];
    const invalid = (): ApiError =>
      new ApiError(422, 'INVALID_WITHHOLDING_INPUT', '필수값이 없거나 형식이 올바르지 않습니다.');
    if (data['paydayId'] === undefined || data['paydayId'] === null || data['paydayId'] === '' || !Number.isInteger(paydayId)) {
      throw invalid();
    }
    if (typeof attributionMonth !== 'string' || !MONTH_PATTERN.test(attributionMonth)) {
      throw invalid();
    }
    if (paymentMonth !== undefined && paymentMonth !== null && paymentMonth !== '') {
      if (typeof paymentMonth !== 'string' || !MONTH_PATTERN.test(paymentMonth)) {
        throw invalid();
      }
    }
    if (typeof reportDivision !== 'string' || reportDivision.trim() === '' || reportDivision.length > 30) {
      throw invalid();
    }
    if (typeof reportType !== 'string' || !REPORT_TYPES.includes(reportType)) {
      throw invalid();
    }
    if (reportData !== undefined && reportData !== null && typeof reportData !== 'string') {
      throw invalid();
    }
    // TODO: 원천세 신고 기준정보(환경설정) 설정 여부 확인 - 입력에 기준정보 테이블이 없어 구현하지 못함
    return transaction(async (db) => {
      const paydays = await db.query(
        'SELECT payday_id FROM payday WHERE payday_id = CAST(:paydayId AS bigint)',
        { paydayId },
      );
      if (paydays.length === 0) {
        throw new ApiError(404, 'PAYROLL_DATA_NOT_FOUND', '집계 대상 급여 데이터가 없습니다.');
      }
      const dup = await db.query(
        `SELECT withholding_report_id FROM withholding_report
         WHERE payday_id = CAST(:paydayId AS bigint)
           AND attribution_month = :attributionMonth
           AND report_division = :reportDivision
           AND report_type = :reportType`,
        { paydayId, attributionMonth, reportDivision, reportType },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'INVALID_STATE', '이미 같은 신고서가 생성되어 있습니다.');
      }
      const rows = await db.query(
        `INSERT INTO withholding_report
           (payday_id, attribution_month, payment_month, report_division, report_type, status, report_data, created_at, updated_at)
         VALUES
           (CAST(:paydayId AS bigint), :attributionMonth, :paymentMonth, :reportDivision, :reportType, '미확정', :reportData, now(), now())
         RETURNING withholding_report_id AS "withholdingReportId", status AS "status", report_data AS "reportData"`,
        {
          paydayId,
          attributionMonth,
          paymentMonth: paymentMonth === '' ? null : (paymentMonth ?? null),
          reportDivision,
          reportType,
          reportData: reportData ?? null,
        },
      );
      return rows[0];
    });
  }

  @Get('/withholding-reports')
  async listWithholdingReports(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자', '시스템 관리자');
    const query = checks.queryOf(req.query);
    const page = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    const sizeRaw = query['size'] === undefined || query['size'] === '' ? DEFAULT_SIZE : Number(query['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
    }
    const size = Math.min(sizeRaw, MAX_SIZE);
    const attributionMonth = query['attributionMonth'] ? String(query['attributionMonth']) : null;
    const reportType = query['reportType'] ? String(query['reportType']) : null;
    const status = query['status'] ? String(query['status']) : null;
    if (reportType !== null && !REPORT_TYPES.includes(reportType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신고 유형이 올바르지 않습니다.');
    }
    if (status !== null && !STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '확정 여부가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const where = `WHERE (CAST(:attributionMonth AS varchar) IS NULL OR attribution_month = CAST(:attributionMonth AS varchar))
          AND (CAST(:reportType AS varchar) IS NULL OR report_type = CAST(:reportType AS varchar))
          AND (CAST(:status AS varchar) IS NULL OR status = CAST(:status AS varchar))`;
      const filter = { attributionMonth, reportType, status };
      const counts = await db.query(
        `SELECT COUNT(*) AS "total" FROM withholding_report ${where}`,
        filter,
      );
      const items = await db.query(
        `SELECT withholding_report_id AS "withholdingReportId",
                attribution_month AS "attributionMonth",
                payment_month AS "paymentMonth",
                report_division AS "reportDivision",
                report_type AS "reportType",
                status AS "status",
                report_data AS "reportData"
           FROM withholding_report ${where}
          ORDER BY withholding_report_id DESC
          LIMIT :size OFFSET :offset`,
        { ...filter, size, offset: page * size },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Patch('/withholding-reports/:withholdingReportId')
  async updateWithholdingReport(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const id = Number(req.params['withholdingReportId']);
    if (!Number.isInteger(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신고서 ID가 올바르지 않습니다.');
    }
    const reportData = data['reportData'];
    if (typeof reportData !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '신고 자료를 입력해 주세요.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status FROM withholding_report WHERE withholding_report_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'WITHHOLDING_REPORT_NOT_FOUND', '신고서를 찾을 수 없습니다.');
      }
      if (rows[0]['status'] !== '미확정') {
        throw new ApiError(409, 'WITHHOLDING_REPORT_CONFIRMED', '확정된 신고서는 취소 절차 없이 수정할 수 없습니다.');
      }
      const updated = await db.query(
        `UPDATE withholding_report
            SET report_data = :reportData, updated_at = now()
          WHERE withholding_report_id = CAST(:id AS bigint)
          RETURNING withholding_report_id AS "withholdingReportId"`,
        { id, reportData },
      );
      return updated[0];
    });
  }

  @Post('/withholding-reports/:withholdingReportId/confirm')
  @HttpCode(200)
  async confirmWithholdingReport(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const id = Number(req.params['withholdingReportId']);
    if (!Number.isInteger(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신고서 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status FROM withholding_report WHERE withholding_report_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'WITHHOLDING_REPORT_NOT_FOUND', '신고서를 찾을 수 없습니다.');
      }
      if (rows[0]['status'] !== '미확정') {
        throw new ApiError(409, 'WITHHOLDING_REPORT_CONFIRMED', '이미 확정된 신고서입니다.');
      }
      const updated = await db.query(
        `UPDATE withholding_report
            SET status = '확정', confirmed_at = now(), updated_at = now()
          WHERE withholding_report_id = CAST(:id AS bigint)
          RETURNING status AS "status", confirmed_at AS "confirmedAt"`,
        { id },
      );
      return updated[0];
    });
  }

  @Get('/withholding-reports/:withholdingReportId/e-filing-file')
  async downloadWithholdingEFilingFile(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const id = Number(req.params['withholdingReportId']);
    if (!Number.isInteger(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신고서 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT status AS "status",
                report_type AS "reportType",
                attribution_month AS "attributionMonth",
                report_data AS "reportData"
           FROM withholding_report
          WHERE withholding_report_id = CAST(:id AS bigint)`,
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'WITHHOLDING_REPORT_NOT_FOUND', '신고서를 찾을 수 없습니다.');
      }
      const row = rows[0];
      if (row['status'] !== '확정') {
        throw new ApiError(409, 'WITHHOLDING_REPORT_NOT_CONFIRMED', '확정되지 않은 신고서입니다.');
      }
      const content = row['reportData'];
      if (typeof content !== 'string' || content.trim() === '') {
        throw new ApiError(422, 'E_FILING_FILE_INVALID', '신고 자료가 비어 있어 전자신고 파일을 만들 수 없습니다.');
      }
      // 가정: 확정된 신고 자료를 국세청 전자신고 텍스트 파일로 변환한다 (시스템은 국세청에 직접 전송하지 않는다)
      return {
        file: {
          fileName: 'withholding-' + String(row['reportType']) + '-' + String(row['attributionMonth']) + '.txt',
          contentType: E_FILING_CONTENT_TYPE,
          content,
        },
      };
    });
  }
}

