import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Tiles,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  Select,
  LookupSelect,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const TYPE_OPTIONS: [string, string][] = [
  ['WITHHOLDING_STATUS', '원천징수이행상황신고서'],
  ['TUITION_REPAYMENT', '학자금상환금명세서'],
  ['LOCAL_INCOME_TAX', '지방소득세 특별징수'],
  ['RESIDENT_TAX_EMPLOYER', '주민세 종업원분'],
  ['PAYMENT_STATEMENT', '지급명세서'],
  ['SUBMISSION_SUMMARY', '제출집계표'],
];
const STATUS_OPTIONS: [string, string][] = [
  ['미확정', '미확정'],
  ['확정', '확정'],
];
const SIZE = 10;

function typeName(value: unknown): string {
  const found = TYPE_OPTIONS.find((o) => o[0] === value);
  return found ? found[1] : String(value ?? '');
}

export default function FnSfr02301Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [draft, setDraft] = useState<Row>({});
  const [applied, setApplied] = useState<Row>({});
  const [creating, setCreating] = useState(false);
  const [selected, setSelected] = useState<Row | null>(null);
  const [editData, setEditData] = useState('');
  const [fileText, setFileText] = useState('');
  const [form, setForm] = useState<Row>({});

  const list = useData<Page>(
    () => call<Page>('GET', '/withholding-reports', role, undefined, { ...applied, page, size: SIZE }),
    [page, applied, role],
  );
  const pending = useData<Page>(
    () => call<Page>('GET', '/withholding-reports', role, undefined, { status: '미확정', page: 0, size: 5 }),
    [role],
  );

  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;
  const pendingRows = pending.data ? pending.data.items : [];

  function reloadAll() {
    list.reload();
    pending.reload();
  }

  function setField(key: string, v: unknown) {
    setForm((prev) => ({ ...prev, [key]: v }));
  }

  function openDetail(row: Row) {
    setSelected(row);
    setEditData(String(row['reportData'] ?? ''));
    setFileText('');
  }

  async function create() {
    if (!form['paydayId'] || !form['attributionMonth'] || !form['reportDivision'] || !form['reportType']) {
      throw new Error('급여 지급일, 귀속연월, 신고구분, 신고 유형을 입력해 주세요.');
    }
    await call('POST', '/withholding-reports', role, {
      paydayId: form['paydayId'],
      attributionMonth: form['attributionMonth'],
      paymentMonth: form['paymentMonth'] || undefined,
      reportDivision: form['reportDivision'],
      reportType: form['reportType'],
      reportData: form['reportData'] || undefined,
    });
    notify('신고서를 생성했습니다.');
    setCreating(false);
    setForm({});
    reloadAll();
  }

  async function save() {
    if (!selected) return;
    const id = selected['withholdingReportId'];
    if (!editData.trim()) {
      throw new Error('신고 자료를 입력해 주세요.');
    }
    await call('PATCH', `/withholding-reports/${id}`, role, { reportData: editData });
    notify('신고서를 수정했습니다.');
    setSelected(null);
    reloadAll();
  }

  async function confirm() {
    if (!selected) return;
    const id = selected['withholdingReportId'];
    await call('POST', `/withholding-reports/${id}/confirm`, role, {});
    notify('신고서를 확정했습니다.');
    setSelected(null);
    reloadAll();
  }

  async function makeFile() {
    if (!selected) return;
    const id = selected['withholdingReportId'];
    const res = await call<Row>('GET', `/withholding-reports/${id}/e-filing-file`, role);
    const file = res['file'] as Row;
    setFileText(String(file['content'] ?? ''));
    notify('전자신고 파일을 생성했습니다.');
  }

  const columns = [
    { key: 'attributionMonth', label: '귀속연월' },
    { key: 'paymentMonth', label: '지급연월' },
    { key: 'reportDivision', label: '신고구분' },
    { key: 'reportType', label: '신고 유형', render: (r: Row) => typeName(r['reportType']) },
    { key: 'status', label: '확정 여부', render: (r: Row) => <Badge value={r['status']} /> },
  ];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>전체 신고서</h2>
        <Tiles items={[['신고서 건수', total]]} />
      </section>
      <section className="box span-4">
        <h2>확정 대기</h2>
        <Tiles items={[['미확정 건수', pending.data ? pending.data.total : 0]]} />
      </section>
      <section className="box span-4">
        <h2>신고서 작성</h2>
        <Band>
          <button onClick={() => setCreating(true)}>신고서 생성</button>
        </Band>
      </section>
      <section className="box span-8">
        <h2>신고서 목록</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied({ ...draft });
          }}
          onReset={() => {
            setDraft({});
            setPage(0);
            setApplied({});
          }}
        >
          <Field label="귀속연월">
            <TextInput value={draft['attributionMonth']} onChange={(v) => setDraft({ ...draft, attributionMonth: v })} placeholder="YYYYMM" />
          </Field>
          <Field label="신고 유형">
            <Select value={draft['reportType']} onChange={(v) => setDraft({ ...draft, reportType: v })} options={TYPE_OPTIONS} />
          </Field>
          <Field label="확정 여부">
            <Select value={draft['status']} onChange={(v) => setDraft({ ...draft, status: v })} options={STATUS_OPTIONS} />
          </Field>
        </Filters>
        {list.error ? <ErrorText text={list.error} /> : null}
        <Band total={total} />
        <DataTable columns={columns} rows={rows} onRowClick={openDetail} empty="신고서가 없습니다." />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>처리 대기</h2>
        <DataTable
          columns={[
            { key: 'attributionMonth', label: '귀속연월' },
            { key: 'reportType', label: '신고 유형', render: (r: Row) => typeName(r['reportType']) },
          ]}
          rows={pendingRows}
          onRowClick={openDetail}
          empty="대기 중인 신고서가 없습니다."
        />
      </section>

      {creating ? (
        <Drawer title="신고서 생성" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="생성">
            <Field label="급여 지급일" required>
              <LookupSelect table="payday" role={role} value={form['paydayId']} onChange={(v) => setField('paydayId', v)} />
            </Field>
            <Field label="귀속연월" required>
              <TextInput value={form['attributionMonth']} onChange={(v) => setField('attributionMonth', v)} placeholder="YYYYMM" />
            </Field>
            <Field label="지급연월">
              <TextInput value={form['paymentMonth']} onChange={(v) => setField('paymentMonth', v)} placeholder="YYYYMM" />
            </Field>
            <Field label="신고구분" required>
              <TextInput value={form['reportDivision']} onChange={(v) => setField('reportDivision', v)} />
            </Field>
            <Field label="신고 유형" required>
              <Select value={form['reportType']} onChange={(v) => setField('reportType', v)} options={TYPE_OPTIONS} />
            </Field>
            <Field label="신고 자료" wide>
              <TextInput multiline value={form['reportData']} onChange={(v) => setField('reportData', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {selected ? (
        <Drawer title="신고서 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['귀속연월', String(selected['attributionMonth'] ?? '')],
              ['지급연월', String(selected['paymentMonth'] ?? '')],
              ['신고구분', String(selected['reportDivision'] ?? '')],
              ['신고 유형', typeName(selected['reportType'])],
              ['확정 여부', <Badge value={selected['status']} />],
            ]}
          />
          {selected['status'] === '미확정' ? (
            <>
              <Form onSubmit={save} submit="수정 저장">
                <Field label="신고 자료" required wide>
                  <TextInput multiline value={editData} onChange={setEditData} />
                </Field>
              </Form>
              <Form onSubmit={confirm} submit="확정" danger note="확정 후에는 취소 절차 없이 수정할 수 없습니다." />
            </>
          ) : (
            <>
              <Pairs items={[['신고 자료', String(selected['reportData'] ?? '')]]} />
              <Form
                onSubmit={makeFile}
                submit="전자신고 파일 생성"
                note="생성한 파일을 내려받아 국세청에 직접 제출합니다."
              >
                {fileText ? (
                  <Field label="전자신고 파일" wide>
                    <TextInput multiline value={fileText} onChange={() => undefined} />
                  </Field>
                ) : null}
              </Form>
            </>
          )}
        </Drawer>
      ) : null}
    </div>
  );
}
